type PricingStrategy = (qty: number) => number;   // Strategy = function type

class Checkout {                                  // Context
  constructor(private readonly pricing: PricingStrategy) {}
  total(qty: number): number { return this.pricing(qty); }
}

const strategies: Record<'retail' | 'bulk', PricingStrategy> = {
  retail: (q) => q * 9.99,
  bulk:   (q) => (q > 100 ? q * 7.49 : q * 9.99),
};
const checkout = new Checkout(strategies.bulk);
